CREATE TABLE "METAECM"."FW_BBS_BOARD"
(	"BOARD_ID" VARCHAR2(64) NOT NULL ENABLE,
     "BOARD_NAME" NVARCHAR2(256) NOT NULL ENABLE,
     "USE_ATTACHMENT_YN" CHAR(1) DEFAULT 'N' NOT NULL ENABLE,
     "USE_COMMENT_YN" CHAR(1) DEFAULT 'N' NOT NULL ENABLE,
     "USE_YN" CHAR(1) DEFAULT 'Y' NOT NULL ENABLE,
     "PERMISSION_TYPE" VARCHAR2(20) DEFAULT 'ADMIN_WRITE' NOT NULL ENABLE,
     "DELETED_YN" CHAR(1) DEFAULT 'N' NOT NULL ENABLE,
     "CREATOR_ID" VARCHAR2(64),
     "CREATOR_NAME" NVARCHAR2(256),
     "CREATED_DATE" DATE,
     "UPDATER_ID" VARCHAR2(64),
     "UPDATER_NAME" NVARCHAR2(256),
