     "VERSION_NUMBER" VARCHAR2(16),
     "VERSION_NOTE" NCLOB,
     "DESCRIPTION" NCLOB,
     "IS_LOCKED" NUMBER(1,0) DEFAULT 0,
     "LOCK_OWNER_ID" VARCHAR2(64),
     "LOCK_OWNER_NAME" NVARCHAR2(256),
     "LOCKED_DATE" DATE,
     "RETENTION" NUMBER(*,0) DEFAULT 0,
     "IS_EXPIRED" NUMBER(1,0) DEFAULT 0,
     "EXPIRED_DATE" DATE,
     "ACL_ID" VARCHAR2(64),
