     "UPDATER_ID" VARCHAR2(64),
     "UPDATER_NAME" NVARCHAR2(256),
     "UPDATED_DATE" DATE,
     "DELETER_ID" VARCHAR2(64),
     "DELETER_NAME" NVARCHAR2(256),
     "DELETED_DATE" DATE,
     "START_PREVENTION_DATE" DATE,
     "END_PREVENTION_DATE" DATE,
     "STANDARD" VARCHAR2(40),
     "ORIGINAL_CREATOR" VARCHAR2(40),
     "ORIGINAL_BILL_DIVISION" VARCHAR2(100),
     "EXPIRATION_DATE" DATE,
     "LASTCHUNKSAVED" TIMESTAMP (6),
     "CHECKINDURINGUNLOCK" CHAR(1) DEFAULT 'N',
     "CHECKEDOUT" CHAR(1) DEFAULT 'N',
     "AUTOVERSION" VARCHAR2(23) DEFAULT 'CheckOutCheckIn',
     "CHECKINONFILECOMPLETE" CHAR(1) DEFAULT 'N',
     "VERSIONCONTROLLED" CHAR(1),
     "CONTENTTYPE" VARCHAR2(255),
     "CHANGENOTES" VARCHAR2(2000),
     "DOC_CODE" VARCHAR2(50),
     PRIMARY KEY ("DOC_ID")
         USING INDEX PCTFREE 10 INITRANS 2 MAXTRANS 255 COMPUTE STATISTICS
         STORAGE(INITIAL 65536 NEXT 1048576 MINEXTENTS 1 MAXEXTENTS 2147483645
         PCTINCREASE 0 FREELISTS 1 FREELIST GROUPS 1
         BUFFER_POOL DEFAULT FLASH_CACHE DEFAULT CELL_FLASH_CACHE DEFAULT)
         TABLESPACE "METAECM_TSPACE"  ENABLE
) SEGMENT CREATION IMMEDIATE
  PCTFREE 10 PCTUSED 40 INITRANS 1 MAXTRANS 255
 NOCOMPRESS LOGGING
  STORAGE(INITIAL 65536 NEXT 1048576 MINEXTENTS 1 MAXEXTENTS 2147483645
  PCTINCREASE 0 FREELISTS 1 FREELIST GROUPS 1
  BUFFER_POOL DEFAULT FLASH_CACHE DEFAULT CELL_FLASH_CACHE DEFAULT)
  TABLESPACE "METAECM_TSPACE"
 LOB ("VERSION_NOTE") STORE AS BASICFILE (
  TABLESPACE "METAECM_TSPACE" ENABLE STORAGE IN ROW CHUNK 8192 RETENTION
  NOCACHE LOGGING
  STORAGE(INITIAL 65536 NEXT 1048576 MINEXTENTS 1 MAXEXTENTS 2147483645
  PCTINCREASE 0 FREELISTS 1 FREELIST GROUPS 1
  BUFFER_POOL DEFAULT FLASH_CACHE DEFAULT CELL_FLASH_CACHE DEFAULT))
 LOB ("DESCRIPTION") STORE AS BASICFILE (
