-- METAECM.FW_MANUAL_NODE definition

CREATE TABLE "METAECM"."FW_MANUAL_NODE"
(	"NODE_ID" VARCHAR2(64) NOT NULL ENABLE,
     "PARENT_ID" VARCHAR2(64),
     "TITLE" NVARCHAR2(256) NOT NULL ENABLE,
     "SORT_ORDER" NUMBER NOT NULL ENABLE,
     "CONTENT_HTML" CLOB,
     "USE_YN" CHAR(1) DEFAULT 'Y' NOT NULL ENABLE,
     "CONTENT_UPDATED_DATE" DATE,
     "CREATOR_ID" VARCHAR2(64),
     "CREATOR_NAME" NVARCHAR2(256),
     "CREATED_DATE" DATE,
     "UPDATER_ID" VARCHAR2(64),
     "UPDATER_NAME" NVARCHAR2(256),
     "UPDATED_DATE" DATE,
     CONSTRAINT "FW_MANUAL_NODE_PK" PRIMARY KEY ("NODE_ID")
         USING INDEX PCTFREE 10 INITRANS 2 MAXTRANS 255 COMPUTE STATISTICS
         STORAGE(INITIAL 65536 NEXT 1048576 MINEXTENTS 1 MAXEXTENTS 2147483645
         PCTINCREASE 0 FREELISTS 1 FREELIST GROUPS 1
         BUFFER_POOL DEFAULT FLASH_CACHE DEFAULT CELL_FLASH_CACHE DEFAULT)
         TABLESPACE "METAECM_TSPACE"  ENABLE
) SEGMENT CREATION IMMEDIATE
  PCTFREE 10 PCTUSED 40 INITRANS 1 MAXTRANS 255
 NOCOMPRESS LOGGING
  STORAGE(INITIAL 65536 NEXT 1048576 MINEXTENTS 1 MAXEXTENTS 2147483645
  PCTINCREASE 0 FREELISTS 1 FREELIST GROUPS 1
  BUFFER_POOL DEFAULT FLASH_CACHE DEFAULT CELL_FLASH_CACHE DEFAULT)
  TABLESPACE "METAECM_TSPACE"
 LOB ("CONTENT_HTML") STORE AS BASICFILE (
  TABLESPACE "METAECM_TSPACE" ENABLE STORAGE IN ROW CHUNK 8192 RETENTION
  NOCACHE LOGGING
  STORAGE(INITIAL 65536 NEXT 1048576 MINEXTENTS 1 MAXEXTENTS 2147483645
  PCTINCREASE 0 FREELISTS 1 FREELIST GROUPS 1
  BUFFER_POOL DEFAULT FLASH_CACHE DEFAULT CELL_FLASH_CACHE DEFAULT)) ;

CREATE UNIQUE INDEX "METAECM"."FW_MANUAL_NODE_PK" ON "METAECM"."FW_MANUAL_NODE" ("NODE_ID")
    PCTFREE 10 INITRANS 2 MAXTRANS 255 COMPUTE STATISTICS
  STORAGE(INITIAL 65536 NEXT 1048576 MINEXTENTS 1 MAXEXTENTS 2147483645
  PCTINCREASE 0 FREELISTS 1 FREELIST GROUPS 1
  BUFFER_POOL DEFAULT FLASH_CACHE DEFAULT CELL_FLASH_CACHE DEFAULT)
  TABLESPACE "METAECM_TSPACE" ;
CREATE UNIQUE INDEX "METAECM"."SYS_IL0000323533C00005$$" ON "METAECM"."FW_MANUAL_NODE" (
                                                                                        PCTFREE 10 INITRANS 2 MAXTRANS 255
  STORAGE(INITIAL 65536 NEXT 1048576 MINEXTENTS 1 MAXEXTENTS 2147483645
  PCTINCREASE 0 FREELISTS 1 FREELIST GROUPS 1
  BUFFER_POOL DEFAULT FLASH_CACHE DEFAULT CELL_FLASH_CACHE DEFAULT)
  TABLESPACE "METAECM_TSPACE"
  PARALLEL (DEGREE 0 INSTANCES 0) ;
CREATE INDEX "METAECM"."FW_MANUAL_NODE_IX01" ON "METAECM"."FW_MANUAL_NODE" ("PARENT_ID", "SORT_ORDER")
    PCTFREE 10 INITRANS 2 MAXTRANS 255 COMPUTE STATISTICS
