-- METAECM.FW_PDF_FILES definition

CREATE TABLE "METAECM"."FW_PDF_FILES"
(	"FILE_ID" VARCHAR2(64),
     "NAME" NVARCHAR2(512),
     "EXTENSION" VARCHAR2(512),
     "CONTENT_SIZE" NUMBER DEFAULT 0,
     "CONTENT_HASH" VARCHAR2(64),
     "CONTENT_IS_ENCRYPTED" NUMBER(1,0) DEFAULT 0,
     "ORG_FILE_ID" VARCHAR2(64),
     "REPOSITORY_NAME" VARCHAR2(32),
     "REPOSITORY_WORKSPACE" VARCHAR2(64),
     "REPOSITORY_PATH" VARCHAR2(256),
     "CREATOR_ID" VARCHAR2(64),
     "CREATOR_NAME" NVARCHAR2(256),
     "CREATED_DATE" DATE DEFAULT SYSDATE,
     "STATUS" VARCHAR2(32) DEFAULT 'PROCESS',
     "RETRYCNT" NUMBER DEFAULT 0,
     "ERRMSG" NCLOB,
     PRIMARY KEY ("FILE_ID")
         USING INDEX PCTFREE 10 INITRANS 2 MAXTRANS 255 COMPUTE STATISTICS
         TABLESPACE "METAECM_TSPACE"  ENABLE
) SEGMENT CREATION DEFERRED
  PCTFREE 10 PCTUSED 40 INITRANS 1 MAXTRANS 255
 NOCOMPRESS LOGGING
  TABLESPACE "METAECM_TSPACE"
 LOB ("ERRMSG") STORE AS BASICFILE (
  TABLESPACE "METAECM_TSPACE" ENABLE STORAGE IN ROW CHUNK 8192 RETENTION
  NOCACHE LOGGING ) ;

