-- METAECM.FW_POPUP_NOTICE definition

CREATE TABLE "METAECM"."FW_POPUP_NOTICE"
(	"NOTICE_ID" VARCHAR2(64) NOT NULL ENABLE,
     "CONTENT_HTML" CLOB,
     "START_DATE" VARCHAR2(8),
     "END_DATE" VARCHAR2(8),
     "MAX_HEIGHT" NUMBER,
     "USE_YN" CHAR(1) DEFAULT 'N' NOT NULL ENABLE,
     "CONTENT_UPDATED_DATE" DATE,
     "CREATOR_ID" VARCHAR2(64),
     "CREATOR_NAME" NVARCHAR2(256),
     "CREATED_DATE" DATE,
     "UPDATER_ID" VARCHAR2(64),
     "UPDATER_NAME" NVARCHAR2(256),
     "UPDATED_DATE" DATE,
     "SOURCE_TYPE" VARCHAR2(10) DEFAULT 'HTML' NOT NULL ENABLE,
     "BOARD_ID" VARCHAR2(64),
     "POST_ID" VARCHAR2(64),
     "WIDTH" NUMBER DEFAULT 520 NOT NULL ENABLE,
     CONSTRAINT "PK_FW_POPUP_NOTICE" PRIMARY KEY ("NOTICE_ID")
         USING INDEX PCTFREE 10 INITRANS 2 MAXTRANS 255 COMPUTE STATISTICS
         STORAGE(INITIAL 65536 NEXT 1048576 MINEXTENTS 1 MAXEXTENTS 2147483645
         PCTINCREASE 0 FREELISTS 1 FREELIST GROUPS 1
         BUFFER_POOL DEFAULT FLASH_CACHE DEFAULT CELL_FLASH_CACHE DEFAULT)
         TABLESPACE "METAECM_TSPACE"  ENABLE,
     CONSTRAINT "CK_FW_POPUP_NOTICE_SRC" CHECK (SOURCE_TYPE IN ('BBS', 'HTML')) ENABLE
) SEGMENT CREATION IMMEDIATE
  PCTFREE 10 PCTUSED 40 INITRANS 1 MAXTRANS 255
 NOCOMPRESS LOGGING
  STORAGE(INITIAL 65536 NEXT 1048576 MINEXTENTS 1 MAXEXTENTS 2147483645
  PCTINCREASE 0 FREELISTS 1 FREELIST GROUPS 1
  BUFFER_POOL DEFAULT FLASH_CACHE DEFAULT CELL_FLASH_CACHE DEFAULT)
  TABLESPACE "METAECM_TSPACE"
 LOB ("CONTENT_HTML") STORE AS BASICFILE (
  TABLESPACE "METAECM_TSPACE" ENABLE STORAGE IN ROW CHUNK 8192 RETENTION
  NOCACHE LOGGING
  STORAGE(INITIAL 65536 NEXT 1048576 MINEXTENTS 1 MAXEXTENTS 2147483645
  PCTINCREASE 0 FREELISTS 1 FREELIST GROUPS 1
  BUFFER_POOL DEFAULT FLASH_CACHE DEFAULT CELL_FLASH_CACHE DEFAULT)) ;

