-- METAECM.FW_SAI_LINKS definition

CREATE TABLE "METAECM"."FW_SAI_LINKS"
(	"TARGET_TYPE" VARCHAR2(16) NOT NULL ENABLE,
     "TARGET_ID" VARCHAR2(64) NOT NULL ENABLE,
     "LINK_YN" CHAR(1) NOT NULL ENABLE,
     "RAG_CODE" VARCHAR2(100),
     "SEARCH_TEXT" NVARCHAR2(1000),
     "ACCESS_DOWNLOAD" CHAR(1) DEFAULT 'N' NOT NULL ENABLE,
     "ACCESS_LINK" CHAR(1) DEFAULT 'N' NOT NULL ENABLE,
     "ACCESS_VIEW" CHAR(1) DEFAULT 'N' NOT NULL ENABLE,
     "CREATOR_ID" VARCHAR2(64),
     "CREATOR_NAME" NVARCHAR2(512),
     "CREATED_DATE" DATE,
     "UPDATER_ID" VARCHAR2(64),
     "UPDATER_NAME" NVARCHAR2(512),
     "UPDATED_DATE" DATE,
     "ACTION_TYPE" VARCHAR2(16),
     CONSTRAINT "CK_FW_SAI_LINKS_LINK_YN" CHECK (LINK_YN IN ('Y', 'N')) ENABLE,
     CONSTRAINT "CK_FW_SAI_LINKS_DOWNLOAD" CHECK (ACCESS_DOWNLOAD IN ('Y', 'N')) ENABLE,
     CONSTRAINT "CK_FW_SAI_LINKS_LINK" CHECK (ACCESS_LINK IN ('Y', 'N')) ENABLE,
     CONSTRAINT "CK_FW_SAI_LINKS_VIEW" CHECK (ACCESS_VIEW IN ('Y', 'N')) ENABLE,
     CONSTRAINT "PK_FW_SAI_LINKS" PRIMARY KEY ("TARGET_TYPE", "TARGET_ID")
         USING INDEX PCTFREE 10 INITRANS 2 MAXTRANS 255 COMPUTE STATISTICS
         STORAGE(INITIAL 65536 NEXT 1048576 MINEXTENTS 1 MAXEXTENTS 2147483645
         PCTINCREASE 0 FREELISTS 1 FREELIST GROUPS 1
         BUFFER_POOL DEFAULT FLASH_CACHE DEFAULT CELL_FLASH_CACHE DEFAULT)
         TABLESPACE "METAECM_TSPACE"  ENABLE,
     CONSTRAINT "CK_FW_SAI_LINKS_TARGET_TYPE" CHECK (TARGET_TYPE IN ('FOLDER', 'DOCUMENT')) ENABLE,
     CONSTRAINT "CK_FW_SAI_LINKS_ACTION_TYPE" CHECK ((TARGET_TYPE = 'FOLDER' AND ACTION_TYPE IN ('CURRENT', 'CHOICE')) OR (TARGET_TYPE = 'DOCUMENT' AND ACTION_TYPE IS NULL)) ENABLE
) SEGMENT CREATION IMMEDIATE
  PCTFREE 10 PCTUSED 40 INITRANS 1 MAXTRANS 255
 NOCOMPRESS LOGGING
  STORAGE(INITIAL 65536 NEXT 1048576 MINEXTENTS 1 MAXEXTENTS 2147483645
  PCTINCREASE 0 FREELISTS 1 FREELIST GROUPS 1
  BUFFER_POOL DEFAULT FLASH_CACHE DEFAULT CELL_FLASH_CACHE DEFAULT)
  TABLESPACE "METAECM_TSPACE" ;

CREATE UNIQUE INDEX "METAECM"."PK_FW_SAI_LINKS" ON "METAECM"."FW_SAI_LINKS" ("TARGET_TYPE", "TARGET_ID")
    PCTFREE 10 INITRANS 2 MAXTRANS 255 COMPUTE STATISTICS
  STORAGE(INITIAL 65536 NEXT 1048576 MINEXTENTS 1 MAXEXTENTS 2147483645
  PCTINCREASE 0 FREELISTS 1 FREELIST GROUPS 1
  BUFFER_POOL DEFAULT FLASH_CACHE DEFAULT CELL_FLASH_CACHE DEFAULT)
  TABLESPACE "METAECM_TSPACE" ;

COMMENT ON TABLE METAECM.FW_SAI_LINKS IS 'SAI 연동 설정. 관리자가 폴더 또는 문서에 저장한 설정 한 건이 한 행이다';
COMMENT ON COLUMN METAECM.FW_SAI_LINKS.TARGET_TYPE IS '설정 대상 종류(FOLDER 폴더, DOCUMENT 문서)';
COMMENT ON COLUMN METAECM.FW_SAI_LINKS.TARGET_ID IS '설정 대상 ID. 폴더는 FW_FOLDERS.FOLDER_ID, 문서는 첫 버전의 FW_DOCUMENTS.DOC_ID(NVL(ROOT_ID, DOC_ID))';
COMMENT ON COLUMN METAECM.FW_SAI_LINKS.LINK_YN IS '연동 여부(Y 연동, N 연동 해제). 폴더 행은 범위(ACTION_TYPE) 안에서 따로 저장한 설정이 없는 폴더와 파일에도 적용된다';
COMMENT ON COLUMN METAECM.FW_SAI_LINKS.RAG_CODE IS '챗봇 유형 코드(SAI 챗봇 유형 view의 RAG_CODE). 연동 해제 행은 비어 있다';
COMMENT ON COLUMN METAECM.FW_SAI_LINKS.SEARCH_TEXT IS 'search 값(1,000자까지). 입력하지 않으면 비어 있다';
COMMENT ON COLUMN METAECM.FW_SAI_LINKS.ACCESS_DOWNLOAD IS 'access download 허용 여부(Y/N)';
COMMENT ON COLUMN METAECM.FW_SAI_LINKS.ACCESS_LINK IS 'access link 허용 여부(Y/N)';
COMMENT ON COLUMN METAECM.FW_SAI_LINKS.ACCESS_VIEW IS 'access view 허용 여부(Y/N)';
COMMENT ON COLUMN METAECM.FW_SAI_LINKS.CREATOR_ID IS '행을 처음 만든 관리자 ID';
COMMENT ON COLUMN METAECM.FW_SAI_LINKS.CREATOR_NAME IS '행을 처음 만든 관리자 이름';
COMMENT ON COLUMN METAECM.FW_SAI_LINKS.CREATED_DATE IS '행을 처음 만든 시각';
COMMENT ON COLUMN METAECM.FW_SAI_LINKS.UPDATER_ID IS '마지막으로 저장한 관리자 ID';
COMMENT ON COLUMN METAECM.FW_SAI_LINKS.UPDATER_NAME IS '마지막으로 저장한 관리자 이름';
COMMENT ON COLUMN METAECM.FW_SAI_LINKS.UPDATED_DATE IS '마지막으로 저장한 시각';
COMMENT ON COLUMN METAECM.FW_SAI_LINKS.ACTION_TYPE IS '폴더 행의 적용 범위(CURRENT 그 폴더와 그 안에 바로 든 파일, CHOICE 그 폴더와 아래 모든 폴더·파일). 문서 행은 비어 있다';


