     "ADMIN_APPROVE_YN" CHAR(1) DEFAULT '0',
     "ADMIN_APPROVE_EXPIRE_DATE" DATE,
     "COMPANY_ID" VARCHAR2(64),
     "COMPANY_NAME" VARCHAR2(128),
     "ADMIN_APPROVE_USER" CHAR(1) DEFAULT 'N',
     "CREATED_OWN" CHAR(1) DEFAULT '1',
