     "AEGIS_EXCEPTION_USE" CHAR(1) DEFAULT 'N',
     "AEGIS_EXCEPTION_USE_FROM" DATE,
     "AEGIS_EXCEPTION_USE_TO" DATE,
     "AD_GB" VARCHAR2(3),
