     "NAS_ID" VARCHAR2(64),
     "SELF_APPROVE_DATE_FROM" DATE,
     "SELF_APPROVE_DATE_TO" DATE,
     "LOCAL_AGENT_INSTALL_YN" VARCHAR2(20),
