     "APPLY_TYPE" VARCHAR2(20) NOT NULL ENABLE,
     "PROJECT_ID" VARCHAR2(11) NOT NULL ENABLE,
     "APPLICANT_DEPT" VARCHAR2(100),
     "FIELD1" VARCHAR2(500),
     "FIELD2" VARCHAR2(500),
     "REASON" VARCHAR2(1000),
     "REMARK" VARCHAR2(1000),
     "STATUS" VARCHAR2(20) DEFAULT 'REQUESTED' NOT NULL ENABLE,
     "CREATOR_ID" VARCHAR2(64) NOT NULL ENABLE,
     "CREATOR_NAME" VARCHAR2(50) NOT NULL ENABLE,
     "CREATED_DATE" DATE NOT NULL ENABLE,
     "UPDATER_ID" VARCHAR2(64),
     "UPDATER_NAME" VARCHAR2(50),
     "UPDATED_DATE" DATE,
     CONSTRAINT "FW_WJG_APPLY_PK" PRIMARY KEY ("APPLY_ID")
         USING INDEX PCTFREE 10 INITRANS 2 MAXTRANS 255 COMPUTE STATISTICS
         TABLESPACE "METAECM_TSPACE"  ENABLE,
     CONSTRAINT "CK_FW_WJG_APPLY_TYPE" CHECK ("APPLY_TYPE" IN ('PARTICIPANT','SUBPROJECT','FOLDER','SECURITY','TRANSFER')) ENABLE,
     CONSTRAINT "CK_FW_WJG_APPLY_STATUS" CHECK ("STATUS" IN ('REQUESTED','APPROVED','REJECTED','WITHDRAWN')) ENABLE
) SEGMENT CREATION DEFERRED
  PCTFREE 10 PCTUSED 40 INITRANS 1 MAXTRANS 255
 NOCOMPRESS LOGGING
  TABLESPACE "METAECM_TSPACE" ;

CREATE UNIQUE INDEX "METAECM"."FW_WJG_APPLY_PK" ON "METAECM"."FW_WJG_APPLY" ("APPLY_ID")
    PCTFREE 10 INITRANS 2 MAXTRANS 255 COMPUTE STATISTICS
  TABLESPACE "METAECM_TSPACE" ;
CREATE INDEX "METAECM"."IX_FW_WJG_APPLY_01" ON "METAECM"."FW_WJG_APPLY" ("APPLY_GROUP_ID")
    PCTFREE 10 INITRANS 2 MAXTRANS 255 COMPUTE STATISTICS
  TABLESPACE "METAECM_TSPACE" ;
CREATE INDEX "METAECM"."IX_FW_WJG_APPLY_02" ON "METAECM"."FW_WJG_APPLY" ("PROJECT_ID")
    PCTFREE 10 INITRANS 2 MAXTRANS 255 COMPUTE STATISTICS
  TABLESPACE "METAECM_TSPACE" ;
CREATE INDEX "METAECM"."IX_FW_WJG_APPLY_03" ON "METAECM"."FW_WJG_APPLY" ("CREATOR_ID", "STATUS")
    PCTFREE 10 INITRANS 2 MAXTRANS 255 COMPUTE STATISTICS
  TABLESPACE "METAECM_TSPACE" ;

COMMENT ON COLUMN METAECM.FW_WJG_APPLY.APPLY_ID IS 'PK(UUID). 신청 묶음 안의 대상 1개 = 1행';
COMMENT ON COLUMN METAECM.FW_WJG_APPLY.APPLY_GROUP_ID IS '신청 묶음 식별자(UUID) - 한 번에 제출한 신청의 행들은 값이 같음';
COMMENT ON COLUMN METAECM.FW_WJG_APPLY.APPLY_TYPE IS 'PARTICIPANT(참여자 추가) | SUBPROJECT(종속 프로젝트 추가) | FOLDER(표준폴더명 변경) | SECURITY(보안등급 변경) | TRANSFER(이관완료 PJT 수정)';
COMMENT ON COLUMN METAECM.FW_WJG_APPLY.PROJECT_ID IS '대상 프로젝트(FW_PROJECT_INFO.PROJECT_INFO_ID, VARCHAR2) - FK 제약은 안 둠(/project/list 검색 결과에서 선택해 저장)';
COMMENT ON COLUMN METAECM.FW_WJG_APPLY.APPLICANT_DEPT IS '신청자 부서명(신청 시점 스냅샷). 신청자 본인 식별은 CREATOR_ID/CREATOR_NAME 재사용';
COMMENT ON COLUMN METAECM.FW_WJG_APPLY.FIELD1 IS 'APPLY_TYPE별 값1 - PARTICIPANT:대상자 사용자 PK(FW_USERS.USER_ID) / SUBPROJECT:종속 프로젝트 PK(FW_PROJECT_INFO.PROJECT_INFO_ID) / FOLDER:기존 표준폴더 / SECURITY:보안등급 / TRANSFER:수정기간';
COMMENT ON COLUMN METAECM.FW_WJG_APPLY.FIELD2 IS 'APPLY_TYPE별 값2 - PARTICIPANT:표준폴더명 / SUBPROJECT:기타요청사항 / FOLDER:변경 표준폴더 / TRANSFER:기타요청사항, SECURITY는 NULL';
COMMENT ON COLUMN METAECM.FW_WJG_APPLY.REASON IS '사유(행별 - SNET 원본 폼도 대상별 사유 컬럼이 따로 있었음)';
COMMENT ON COLUMN METAECM.FW_WJG_APPLY.REMARK IS '비고(신청 묶음 전체 공통, 행마다 중복 저장 - 비정규화)';
COMMENT ON COLUMN METAECM.FW_WJG_APPLY.STATUS IS 'REQUESTED(신청, 기본) | APPROVED | REJECTED | WITHDRAWN(신청자 철회) - 행별로 둬서 관리자가 대상별 승인/반려 가능';


