-- METAECM.MIGRATION_DOCUMENT_MAP definition

CREATE TABLE "METAECM"."MIGRATION_DOCUMENT_MAP"
(	"LEGACY_OID" VARCHAR2(11) NOT NULL ENABLE,
     "SOURCE_TYPE" VARCHAR2(15) NOT NULL ENABLE,
     "PROJECT_NO" NVARCHAR2(1000),
     "LEGACY_FOLDER_OID" VARCHAR2(11),
     "NEW_FOLDER_ID" VARCHAR2(64),
     "NEW_DOC_ID" VARCHAR2(64),
     "NEW_FILE_ID" VARCHAR2(64),
     "STATUS" VARCHAR2(10) DEFAULT 'PENDING',
     "ERROR_MESSAGE" NVARCHAR2(2000),
     "ATTEMPT_COUNT" NUMBER DEFAULT 0,
     "LEGACY_CREATED_AT" DATE,
     "MIGRATED_AT" DATE,
     "CREATED_DATE" DATE DEFAULT SYSDATE,
     "UPDATED_DATE" DATE,
     CONSTRAINT "PK_MIGRATION_DOCUMENT_MAP" PRIMARY KEY ("LEGACY_OID", "SOURCE_TYPE")
         USING INDEX PCTFREE 10 INITRANS 2 MAXTRANS 255 COMPUTE STATISTICS
         STORAGE(INITIAL 65536 NEXT 1048576 MINEXTENTS 1 MAXEXTENTS 2147483645
         PCTINCREASE 0 FREELISTS 1 FREELIST GROUPS 1
         BUFFER_POOL DEFAULT FLASH_CACHE DEFAULT CELL_FLASH_CACHE DEFAULT)
         TABLESPACE "METAECM_TSPACE"  ENABLE
) SEGMENT CREATION IMMEDIATE
  PCTFREE 10 PCTUSED 40 INITRANS 1 MAXTRANS 255
 NOCOMPRESS LOGGING
  STORAGE(INITIAL 65536 NEXT 1048576 MINEXTENTS 1 MAXEXTENTS 2147483645
  PCTINCREASE 0 FREELISTS 1 FREELIST GROUPS 1
  BUFFER_POOL DEFAULT FLASH_CACHE DEFAULT CELL_FLASH_CACHE DEFAULT)
  TABLESPACE "METAECM_TSPACE" ;

CREATE UNIQUE INDEX "METAECM"."PK_MIGRATION_DOCUMENT_MAP" ON "METAECM"."MIGRATION_DOCUMENT_MAP" ("LEGACY_OID", "SOURCE_TYPE")
    PCTFREE 10 INITRANS 2 MAXTRANS 255 COMPUTE STATISTICS
  STORAGE(INITIAL 65536 NEXT 1048576 MINEXTENTS 1 MAXEXTENTS 2147483645
  PCTINCREASE 0 FREELISTS 1 FREELIST GROUPS 1
  BUFFER_POOL DEFAULT FLASH_CACHE DEFAULT CELL_FLASH_CACHE DEFAULT)
  TABLESPACE "METAECM_TSPACE" ;

COMMENT ON TABLE METAECM.MIGRATION_DOCUMENT_MAP IS '[이관] 문서/파일 매핑';
COMMENT ON COLUMN METAECM.MIGRATION_DOCUMENT_MAP.LEGACY_OID IS '레거시 OID';
COMMENT ON COLUMN METAECM.MIGRATION_DOCUMENT_MAP.SOURCE_TYPE IS '원천유형(DOCUMENT/PROJECT_FILE)';
COMMENT ON COLUMN METAECM.MIGRATION_DOCUMENT_MAP.PROJECT_NO IS '프로젝트번호';
COMMENT ON COLUMN METAECM.MIGRATION_DOCUMENT_MAP.LEGACY_FOLDER_OID IS '레거시 폴더 OID';
COMMENT ON COLUMN METAECM.MIGRATION_DOCUMENT_MAP.NEW_FOLDER_ID IS '신규 폴더ID';
COMMENT ON COLUMN METAECM.MIGRATION_DOCUMENT_MAP.NEW_DOC_ID IS '신규 문서ID';
COMMENT ON COLUMN METAECM.MIGRATION_DOCUMENT_MAP.NEW_FILE_ID IS '신규 파일ID';
COMMENT ON COLUMN METAECM.MIGRATION_DOCUMENT_MAP.STATUS IS '상태(PENDING/SUCCESS/FAILED/SKIPPED)';
COMMENT ON COLUMN METAECM.MIGRATION_DOCUMENT_MAP.ERROR_MESSAGE IS '오류메시지';
COMMENT ON COLUMN METAECM.MIGRATION_DOCUMENT_MAP.ATTEMPT_COUNT IS '시도횟수';
COMMENT ON COLUMN METAECM.MIGRATION_DOCUMENT_MAP.LEGACY_CREATED_AT IS '레거시 생성일시';
COMMENT ON COLUMN METAECM.MIGRATION_DOCUMENT_MAP.MIGRATED_AT IS '이관일시';
COMMENT ON COLUMN METAECM.MIGRATION_DOCUMENT_MAP.CREATED_DATE IS '등록일시';
COMMENT ON COLUMN METAECM.MIGRATION_DOCUMENT_MAP.UPDATED_DATE IS '수정일시';


