COMMENT ON TABLE METAECM.MIGRATION_FILE_MAP IS '[이관] 파일 매핑';
COMMENT ON COLUMN METAECM.MIGRATION_FILE_MAP.LEGACY_FILE_OID IS '레거시 파일 OID';
COMMENT ON COLUMN METAECM.MIGRATION_FILE_MAP.LEGACY_DOC_OID IS '레거시 문서 OID';
COMMENT ON COLUMN METAECM.MIGRATION_FILE_MAP.PROJECT_NO IS '프로젝트번호';
COMMENT ON COLUMN METAECM.MIGRATION_FILE_MAP.NEW_DOC_ID IS '신규 문서ID';
COMMENT ON COLUMN METAECM.MIGRATION_FILE_MAP.NEW_FILE_ID IS '신규 파일ID';
COMMENT ON COLUMN METAECM.MIGRATION_FILE_MAP.SOURCE_MD5 IS '원본 MD5(대문자)';
COMMENT ON COLUMN METAECM.MIGRATION_FILE_MAP.CONTENT_HASH IS '등록 SHA-256';
COMMENT ON COLUMN METAECM.MIGRATION_FILE_MAP.CONTENT_SIZE IS '등록 크기';
