COMMENT ON COLUMN METAECM.PLAN_TABLE.PARENT_ID IS '상위폴더 ID';
COMMENT ON COLUMN METAECM.PLAN_TABLE."POSITION" IS '위치';
COMMENT ON COLUMN METAECM.PLAN_TABLE.COST IS '비용';
COMMENT ON COLUMN METAECM.PLAN_TABLE."CARDINALITY" IS '카디널리티';
COMMENT ON COLUMN METAECM.PLAN_TABLE.BYTES IS '바이트';
