-- METAECM.PROJECT_ACL_MATRIX definition

CREATE TABLE "METAECM"."PROJECT_ACL_MATRIX"
(	"GRADE" VARCHAR2(4) NOT NULL ENABLE,
     "STATUS" VARCHAR2(4) NOT NULL ENABLE,
     "ACL_SUFFIX" VARCHAR2(16) NOT NULL ENABLE,
     "PERMS" VARCHAR2(10) NOT NULL ENABLE,
     CONSTRAINT "CK_PROJECT_ACL_MATRIX" CHECK (GRADE IN ('L1', 'GEN') AND STATUS IN ('ING', 'PRE', 'DONE')
         AND REGEXP_LIKE(PERMS, '^[RW-]{10}$')) ENABLE,
     CONSTRAINT "PK_PROJECT_ACL_MATRIX" PRIMARY KEY ("GRADE", "STATUS", "ACL_SUFFIX")
         USING INDEX PCTFREE 10 INITRANS 2 MAXTRANS 255 COMPUTE STATISTICS
         STORAGE(INITIAL 65536 NEXT 1048576 MINEXTENTS 1 MAXEXTENTS 2147483645
         PCTINCREASE 0 FREELISTS 1 FREELIST GROUPS 1
         BUFFER_POOL DEFAULT FLASH_CACHE DEFAULT CELL_FLASH_CACHE DEFAULT)
         TABLESPACE "METAECM_TSPACE"  ENABLE
) SEGMENT CREATION IMMEDIATE
  PCTFREE 10 PCTUSED 40 INITRANS 1 MAXTRANS 255
 NOCOMPRESS LOGGING
  STORAGE(INITIAL 65536 NEXT 1048576 MINEXTENTS 1 MAXEXTENTS 2147483645
  PCTINCREASE 0 FREELISTS 1 FREELIST GROUPS 1
  BUFFER_POOL DEFAULT FLASH_CACHE DEFAULT CELL_FLASH_CACHE DEFAULT)
  TABLESPACE "METAECM_TSPACE" ;

CREATE UNIQUE INDEX "METAECM"."PK_PROJECT_ACL_MATRIX" ON "METAECM"."PROJECT_ACL_MATRIX" ("GRADE", "STATUS", "ACL_SUFFIX")
    PCTFREE 10 INITRANS 2 MAXTRANS 255 COMPUTE STATISTICS
  STORAGE(INITIAL 65536 NEXT 1048576 MINEXTENTS 1 MAXEXTENTS 2147483645
  PCTINCREASE 0 FREELISTS 1 FREELIST GROUPS 1
  BUFFER_POOL DEFAULT FLASH_CACHE DEFAULT CELL_FLASH_CACHE DEFAULT)
  TABLESPACE "METAECM_TSPACE" ;


-- METAECM.PROPERTY definition

CREATE TABLE "METAECM"."PROPERTY"
(	"ID" NUMBER(5,0) NOT NULL ENABLE,
     "ITEMID" VARCHAR2(64) NOT NULL ENABLE,
     "NAME" NVARCHAR2(255) NOT NULL ENABLE,
     "NAMESPACE" NVARCHAR2(100),
     "PROPVAL" NVARCHAR2(255) NOT NULL ENABLE,
     CONSTRAINT "PROPERTY_PK" UNIQUE ("ID")
         USING INDEX PCTFREE 10 INITRANS 2 MAXTRANS 255 COMPUTE STATISTICS
         TABLESPACE "METAECM_TSPACE"  ENABLE
) SEGMENT CREATION DEFERRED
  PCTFREE 10 PCTUSED 40 INITRANS 1 MAXTRANS 255
 NOCOMPRESS LOGGING
  TABLESPACE "METAECM_TSPACE" ;

CREATE OR REPLACE TRIGGER "METAECM"."TRG_PROPERY_ID_INSERT"
BEFORE INSERT ON "PROPERTY"
FOR EACH ROW
 WHEN (new.ID IS NULL) BEGIN
SELECT PROPERTY_SEQ.NEXTVAL INTO :new.ID FROM dual;
END;
/
ALTER TRIGGER "METAECM"."TRG_PROPERY_ID_INSERT" ENABLE;

CREATE UNIQUE INDEX "METAECM"."PROPERTY_PK" ON "METAECM"."PROPERTY" ("ID")
    PCTFREE 10 INITRANS 2 MAXTRANS 255 COMPUTE STATISTICS
  TABLESPACE "METAECM_TSPACE" ;

COMMENT ON TABLE METAECM.PROPERTY IS '속성';
COMMENT ON COLUMN METAECM.PROPERTY.ID IS '채팅 ID';
COMMENT ON COLUMN METAECM.PROPERTY.ITEMID IS '아이템 ID';
COMMENT ON COLUMN METAECM.PROPERTY.NAME IS '파일명';
COMMENT ON COLUMN METAECM.PROPERTY.NAMESPACE IS '네임스페이스';
COMMENT ON COLUMN METAECM.PROPERTY.PROPVAL IS '속성값';


