CREATE TABLE "METAECM"."REPOSITORY"
(	"ID" NUMBER(5,0) NOT NULL ENABLE,
     "NAME" NVARCHAR2(255) NOT NULL ENABLE,
     "CREATED" TIMESTAMP (6) NOT NULL ENABLE,
     "MODIFIED" TIMESTAMP (6) NOT NULL ENABLE,
     "PARENT" NUMBER(5,0) NOT NULL ENABLE,
     "ITEMTYPE" NUMBER(5,0) NOT NULL ENABLE,
     "TOTALCONTENTLENGTH" NUMBER(10,0) NOT NULL ENABLE,
     "LASTCHUNKSAVED" TIMESTAMP (6) NOT NULL ENABLE,
     "CONTENTTYPE" VARCHAR2(255),
     "CONTENT" BLOB,
     "SERIALNUMBER" NUMBER(*,0) DEFAULT 0 NOT NULL ENABLE,
     "VERSIONCONTROLLED" CHAR(1),
     "CHECKINDURINGUNLOCK" CHAR(1),
     "CHECKEDOUT" CHAR(1),
     "AUTOVERSION" VARCHAR2(23) NOT NULL ENABLE,
     "CHECKINONFILECOMPLETE" CHAR(1),
     "CREATORDISPLAYNAME" VARCHAR2(255),
     "CHANGENOTES" VARCHAR2(2000),
     CONSTRAINT "REPOSITORY_KEY" PRIMARY KEY ("ID")
         USING INDEX PCTFREE 10 INITRANS 2 MAXTRANS 255 COMPUTE STATISTICS
         TABLESPACE "METAECM_TSPACE"  ENABLE,
     CHECK ("CHECKINONFILECOMPLETE" in ( 'Y', 'N' )) ENABLE,
     CHECK ("CHECKEDOUT" in ( 'Y', 'N' )) ENABLE,
     CHECK ("CHECKINDURINGUNLOCK" in ( 'Y', 'N' )) ENABLE,
     CHECK ("VERSIONCONTROLLED" in ( 'Y', 'N' )) ENABLE
) SEGMENT CREATION DEFERRED
  PCTFREE 10 PCTUSED 40 INITRANS 1 MAXTRANS 255
 NOCOMPRESS LOGGING
  TABLESPACE "METAECM_TSPACE"
 LOB ("CONTENT") STORE AS BASICFILE (
  TABLESPACE "METAECM_TSPACE" ENABLE STORAGE IN ROW CHUNK 8192 RETENTION
  NOCACHE LOGGING )  ENABLE ROW MOVEMENT ;

CREATE UNIQUE INDEX "METAECM"."SYS_IL0000322567C00010$$" ON "METAECM"."REPOSITORY" (
                                                                                    PCTFREE 10 INITRANS 2 MAXTRANS 255
