CREATE TABLE "METAECM"."UNITY_ORGANIZATION"
(	"CORP_CD" VARCHAR2(3) NOT NULL ENABLE,
     "DEPT_CD" VARCHAR2(15) NOT NULL ENABLE,
     "DEPT_NAME" VARCHAR2(150),
     "PG_CD" VARCHAR2(3),
     "PG_NAME" VARCHAR2(90),
     "PU_CD" VARCHAR2(5),
     "PU_NAME" VARCHAR2(90),
     "PLACE_CD" VARCHAR2(5),
     "PLACE_NAME" VARCHAR2(45),
     "PARENT_CD" VARCHAR2(30),
     "SELF_DE" VARCHAR2(30),
     "OPEN_DT" VARCHAR2(12),
     "CLOSE_DT" VARCHAR2(12),
     "MK_DT" VARCHAR2(12),
     "DEPT_S_NAME" VARCHAR2(150),
     "DEPT_YN" VARCHAR2(2),
     "TRAN_GB" VARCHAR2(2),
     "CORP_NAME" VARCHAR2(75),
     "CORP_GU" VARCHAR2(15),
     "COOP_YN" VARCHAR2(2),
     "MK_USER" VARCHAR2(15),
     "PARENT_DEPT" NUMBER,
     "SELF_DEPT" NUMBER,
     "SORT_DEPT" NUMBER,
     "DEPT_ENG_NAME" VARCHAR2(300),
     "DEPT_ENG_S_NAME" VARCHAR2(150),
     "PG_ENG_NAME" VARCHAR2(90),
     "PU_ENG_NAME" VARCHAR2(90),
     "PLACE_ENG_NAME" VARCHAR2(45),
     "CORP_ENG_NAME" VARCHAR2(75),
     "DEPT_CHA_NAME" VARCHAR2(230),
     "DEPT_CHA_S_NAME" VARCHAR2(230),
     "PG_CHA_NAME" VARCHAR2(140),
     "PU_CHA_NAME" VARCHAR2(140),
     "PLACE_CHA_NAME" VARCHAR2(70),
     "CORP_CHA_NAME" VARCHAR2(120),
     "PICODE" CHAR(20),
     "PISTAT" CHAR(1),
     "PIDATE" CHAR(8),
     "PITIME" CHAR(6),
     "PIUSER" CHAR(20),
     "PIMSG" CHAR(200),
     "PIMSGID" CHAR(32),
     CONSTRAINT "UNITY_ORGANIZATION_PK" PRIMARY KEY ("CORP_CD", "DEPT_CD")
         USING INDEX PCTFREE 10 INITRANS 2 MAXTRANS 255 COMPUTE STATISTICS
         TABLESPACE "METAECM_TSPACE"  ENABLE
) SEGMENT CREATION DEFERRED
  PCTFREE 10 PCTUSED 40 INITRANS 1 MAXTRANS 255
 NOCOMPRESS LOGGING
  TABLESPACE "METAECM_TSPACE" ;

