-- METAECM.VERSION definition

CREATE TABLE "METAECM"."VERSION"
(	"ID" NUMBER(5,0) NOT NULL ENABLE,
     "ITEMID" VARCHAR2(64) NOT NULL ENABLE,
     "VERSIONNUMBER" NUMBER(5,0) NOT NULL ENABLE,
     "NAME" NVARCHAR2(255) NOT NULL ENABLE,
     "CHANGENOTES" NVARCHAR2(2000),
     "CREATORDISPLAYNAME" NVARCHAR2(255) NOT NULL ENABLE,
     "CREATED" TIMESTAMP (6) NOT NULL ENABLE,
     "CONTENTTYPE" VARCHAR2(255),
     "CONTENT" BLOB,
     CONSTRAINT "VERSION_PK" PRIMARY KEY ("ID")
         USING INDEX PCTFREE 10 INITRANS 2 MAXTRANS 255 COMPUTE STATISTICS
         TABLESPACE "METAECM_TSPACE"  ENABLE
) SEGMENT CREATION DEFERRED
  PCTFREE 10 PCTUSED 40 INITRANS 1 MAXTRANS 255
 NOCOMPRESS LOGGING
  TABLESPACE "METAECM_TSPACE"
 LOB ("CONTENT") STORE AS BASICFILE (
  TABLESPACE "METAECM_TSPACE" ENABLE STORAGE IN ROW CHUNK 8192 RETENTION
  NOCACHE LOGGING ) ;

CREATE UNIQUE INDEX "METAECM"."SYS_IL0000322586C00009$$" ON "METAECM"."VERSION" (
                                                                                 PCTFREE 10 INITRANS 2 MAXTRANS 255
  STORAGE( INITIAL 65536 NEXT 1048576 MAXEXTENTS 2147483645
  BUFFER_POOL DEFAULT FLASH_CACHE DEFAULT CELL_FLASH_CACHE DEFAULT)
  TABLESPACE "METAECM_TSPACE"
  PARALLEL (DEGREE 0 INSTANCES 0) ;
CREATE UNIQUE INDEX "METAECM"."IDX_VERSION" ON "METAECM"."VERSION" ("ITEMID", "VERSIONNUMBER")
    PCTFREE 10 INITRANS 2 MAXTRANS 255 COMPUTE STATISTICS
  TABLESPACE "METAECM_TSPACE" ;
CREATE UNIQUE INDEX "METAECM"."VERSION_PK" ON "METAECM"."VERSION" ("ID")
    PCTFREE 10 INITRANS 2 MAXTRANS 255 COMPUTE STATISTICS
  TABLESPACE "METAECM_TSPACE" ;

COMMENT ON TABLE METAECM.VERSION IS '버전';
COMMENT ON COLUMN METAECM.VERSION.ID IS '채팅 ID';
COMMENT ON COLUMN METAECM.VERSION.ITEMID IS '아이템 ID';
COMMENT ON COLUMN METAECM.VERSION.VERSIONNUMBER IS '버전 번호';
COMMENT ON COLUMN METAECM.VERSION.NAME IS '파일명';
COMMENT ON COLUMN METAECM.VERSION.CHANGENOTES IS '변경 메모';
COMMENT ON COLUMN METAECM.VERSION.CREATORDISPLAYNAME IS '생성자 표시명';
COMMENT ON COLUMN METAECM.VERSION.CREATED IS '생성 일시';
COMMENT ON COLUMN METAECM.VERSION.CONTENTTYPE IS '콘텐츠 유형';
