-- METAECM.VERSIONPROPERTY definition

CREATE TABLE "METAECM"."VERSIONPROPERTY"
(	"ID" NUMBER(5,0) NOT NULL ENABLE,
     "VERSIONID" NUMBER(5,0) NOT NULL ENABLE,
     "NAME" NVARCHAR2(255) NOT NULL ENABLE,
     "NAMESPACE" NVARCHAR2(100),
     "PROPVAL" NVARCHAR2(255) NOT NULL ENABLE,
     CONSTRAINT "VERSIONPROPERTY_PK" UNIQUE ("ID")
         USING INDEX PCTFREE 10 INITRANS 2 MAXTRANS 255 COMPUTE STATISTICS
         TABLESPACE "METAECM_TSPACE"  ENABLE
) SEGMENT CREATION DEFERRED
  PCTFREE 10 PCTUSED 40 INITRANS 1 MAXTRANS 255
 NOCOMPRESS LOGGING
  TABLESPACE "METAECM_TSPACE" ;

CREATE OR REPLACE TRIGGER "METAECM"."TRG_VERSIONPROPERY_ID_INSERT"
BEFORE INSERT ON "VERSIONPROPERTY"
FOR EACH ROW
 WHEN (new.ID IS NULL) BEGIN
SELECT VERSIONPROPERTY_SEQ.NEXTVAL INTO :new.ID FROM dual;
END;
/
ALTER TRIGGER "METAECM"."TRG_VERSIONPROPERY_ID_INSERT" ENABLE;

CREATE UNIQUE INDEX "METAECM"."IDX_VERSIONPROPERTY" ON "METAECM"."VERSIONPROPERTY" ("VERSIONID", "NAME", "NAMESPACE")
    PCTFREE 10 INITRANS 2 MAXTRANS 255 COMPUTE STATISTICS
  TABLESPACE "METAECM_TSPACE" ;
CREATE UNIQUE INDEX "METAECM"."VERSIONPROPERTY_PK" ON "METAECM"."VERSIONPROPERTY" ("ID")
    PCTFREE 10 INITRANS 2 MAXTRANS 255 COMPUTE STATISTICS
  TABLESPACE "METAECM_TSPACE" ;

COMMENT ON TABLE METAECM.VERSIONPROPERTY IS '버전 속성';
COMMENT ON COLUMN METAECM.VERSIONPROPERTY.ID IS '채팅 ID';
