COMMENT ON TABLE METAECM.FW_BBS_POST IS 'BBS 게시물';
COMMENT ON COLUMN METAECM.FW_BBS_POST.POST_ID IS 'SOURCE_TYPE';
COMMENT ON COLUMN METAECM.FW_BBS_POST.BOARD_ID IS '게시판 ID';
COMMENT ON COLUMN METAECM.FW_BBS_POST.TITLE IS '제목';
COMMENT ON COLUMN METAECM.FW_BBS_POST.CONTENT_HTML IS '본문 HTML';
COMMENT ON COLUMN METAECM.FW_BBS_POST.IS_NOTICE_YN IS '목록 상단 고정 여부';
COMMENT ON COLUMN METAECM.FW_BBS_POST.VIEW_COUNT IS '조회수';
COMMENT ON COLUMN METAECM.FW_BBS_POST.DELETED_YN IS '소프트삭제됨 여부';
COMMENT ON COLUMN METAECM.FW_BBS_POST.CREATOR_ID IS '등록자 ID';
COMMENT ON COLUMN METAECM.FW_BBS_POST.CREATOR_NAME IS '등록자명';
COMMENT ON COLUMN METAECM.FW_BBS_POST.CREATED_DATE IS '등록일';
COMMENT ON COLUMN METAECM.FW_BBS_POST.UPDATER_ID IS '수정자 ID';
COMMENT ON COLUMN METAECM.FW_BBS_POST.UPDATER_NAME IS '수정자 이름';
COMMENT ON COLUMN METAECM.FW_BBS_POST.UPDATED_DATE IS '수정일';
COMMENT ON COLUMN METAECM.FW_BBS_POST.SECRET_YN IS 'Y=비밀글(작성자 본인+관리자+비밀번호 일치자만 본문/첨부 열람). 답변은 insert 시 스레드 루트값을 그대로 복사(denormalized, ROOT_CREATOR_ID와 동일 관례) - 제목/작성자/작성일은 비밀글이어도 목록에 그대로 노출, 본문/첨부만 잠김';
COMMENT ON COLUMN METAECM.FW_BBS_POST.PASSWORD_HASH IS 'SECRET_YN=Y일 때만 사용. PBKDF2WithHmacSHA256(salt=PASSWORD_SALT) 해시값(hex). 원문 비밀번호는 저장 안 함';
COMMENT ON COLUMN METAECM.FW_BBS_POST.PASSWORD_SALT IS 'SECRET_YN=Y일 때만 사용. 글 작성 시 랜덤 생성(hex)';


